import unittest

import runner
from tasks import cleanup


class TestTasks(unittest.TestCase):
    def test_cleanup_drops_temporary_files(self):
        self.assertEqual(cleanup(['a.txt', 'b.tmp']), ['a.txt'])

    def test_the_nightly_job_runs(self):
        self.assertEqual(runner.run('nightly'), 'report sent')
